/**
 * CurveTrace records which values of a periodic coordinate have been visited
 * and the model outputs at each visited bin. The graph draws only what the
 * trace contains, so the curve is literally generated by the motion.
 *
 * Bins are tagged with the revolution in which they were last visited so the
 * current revolution can be drawn solid and the previous one faded.
 */

// Must fit in the Int32Array that stores revolutions (MIN_SAFE_INTEGER would wrap to 1).
const NEVER = -0x80000000;

export interface CurveTrace {
  readonly binsPerPeriod: number;
  readonly period: number;
  readonly channels: readonly string[];
  /** Revolution index at which each bin was last visited (NEVER if unvisited). */
  readonly revolutionOf: Int32Array;
  /** Channel values sampled at each bin centre. */
  readonly values: Readonly<Record<string, Float64Array>>;
  /** Revolution containing the most recent sweep end point. */
  currentRevolution: number;
  /** Most recent revolution different from the current one, if any. */
  previousRevolution: number;
  /** Incremented on every mutation so renderers can skip redundant work. */
  version: number;
}

export type Sampler = (coordinate: number) => Readonly<Record<string, number>>;

export function createTrace(channels: readonly string[], period: number, binsPerPeriod = 720): CurveTrace {
  const values: Record<string, Float64Array> = {};
  for (const channel of channels) values[channel] = new Float64Array(binsPerPeriod);
  return {
    binsPerPeriod,
    period,
    channels,
    revolutionOf: new Int32Array(binsPerPeriod).fill(NEVER),
    values,
    currentRevolution: 0,
    previousRevolution: NEVER,
    version: 0,
  };
}

export function clearTrace(trace: CurveTrace): void {
  trace.revolutionOf.fill(NEVER);
  trace.currentRevolution = 0;
  trace.previousRevolution = NEVER;
  trace.version++;
}

export function revolutionAt(trace: CurveTrace, coordinate: number): number {
  return Math.floor(coordinate / trace.period + 1e-12);
}

export function binAt(trace: CurveTrace, coordinate: number): number {
  const phase = coordinate / trace.period - revolutionAt(trace, coordinate);
  return Math.min(trace.binsPerPeriod - 1, Math.max(0, Math.floor(phase * trace.binsPerPeriod)));
}

/** Coordinate (within one period, [0, period)) of the centre of a bin. */
export function binCenter(trace: CurveTrace, bin: number): number {
  return ((bin + 0.5) / trace.binsPerPeriod) * trace.period;
}

function markBin(trace: CurveTrace, coordinate: number, sample: Sampler): void {
  const bin = binAt(trace, coordinate);
  const revolution = revolutionAt(trace, coordinate);
  if (trace.revolutionOf[bin] === revolution) return;
  trace.revolutionOf[bin] = revolution;
  const sampled = sample(binCenter(trace, bin));
  for (const channel of trace.channels) {
    const column = trace.values[channel];
    const value = sampled[channel];
    if (column && value !== undefined) column[bin] = value;
  }
}

function setCurrentRevolution(trace: CurveTrace, revolution: number): void {
  if (revolution !== trace.currentRevolution) {
    trace.previousRevolution = trace.currentRevolution;
    trace.currentRevolution = revolution;
  }
}

/**
 * Mark every bin swept while the coordinate moves from `from` to `to`
 * (in either direction). Sweeps longer than one period only mark the final
 * period, which is all that can be displayed.
 */
export function sweepTrace(trace: CurveTrace, from: number, to: number, sample: Sampler): void {
  const distance = to - from;
  const sign = Math.sign(distance);
  let start = from;
  if (Math.abs(distance) > trace.period) start = to - sign * trace.period;

  const stepSize = trace.period / trace.binsPerPeriod / 2;
  const steps = Math.ceil(Math.abs(to - start) / stepSize);
  for (let i = 0; i <= steps; i++) {
    const coordinate = i === steps ? to : start + sign * i * stepSize;
    setCurrentRevolution(trace, revolutionAt(trace, coordinate));
    markBin(trace, coordinate, sample);
  }
  trace.version++;
}

/** Mark only the bin at `at` — used for jumps that should not paint a path. */
export function markPoint(trace: CurveTrace, at: number, sample: Sampler): void {
  setCurrentRevolution(trace, revolutionAt(trace, at));
  markBin(trace, at, sample);
  trace.version++;
}

export type BinVisit = "current" | "previous" | "none";

export function visitOf(trace: CurveTrace, bin: number): BinVisit {
  const revolution = trace.revolutionOf[bin];
  if (revolution === trace.currentRevolution) return "current";
  if (revolution === trace.previousRevolution && revolution !== NEVER) return "previous";
  return "none";
}

export interface TraceSegment {
  visit: Exclude<BinVisit, "none">;
  /** Consecutive bin indices, in ascending order. */
  bins: number[];
}

/** Group visited bins into contiguous runs so a graph can stroke each as a path. */
export function traceSegments(trace: CurveTrace): TraceSegment[] {
  const segments: TraceSegment[] = [];
  let current: TraceSegment | null = null;
  for (let bin = 0; bin < trace.binsPerPeriod; bin++) {
    const visit = visitOf(trace, bin);
    if (visit === "none") {
      current = null;
      continue;
    }
    if (!current || current.visit !== visit) {
      current = { visit, bins: [] };
      segments.push(current);
    }
    current.bins.push(bin);
  }
  return segments;
}

/** Fraction of one period drawn (current or previous revolution), in [0, 1]. */
export function traceCoverage(trace: CurveTrace): number {
  let count = 0;
  for (let bin = 0; bin < trace.binsPerPeriod; bin++) if (visitOf(trace, bin) !== "none") count++;
  return count / trace.binsPerPeriod;
}

export function visitedCount(trace: CurveTrace, visit: Exclude<BinVisit, "none"> = "current"): number {
  let count = 0;
  for (let bin = 0; bin < trace.binsPerPeriod; bin++) if (visitOf(trace, bin) === visit) count++;
  return count;
}
